65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
76	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
77	     */
78	    private static final Pattern EMAIL_PATTERN =
79	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
80	
81	    /**
82	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
83	     * new owner's id, customerCode, registrationDate and membershipLevel.
84	     */
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
86	
87	    /**
88	     * Common street-type abbreviations expanded during address normalization, keyed by the
89	     * upper-cased abbreviation.
90	     */
91	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
92	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
93	
94	    /**
95	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
96	     * city already holds this many owners.
97	     */
98	    private static final int CITY_CAPACITY = 50;
99	
100	    /**
101	     * Maximum number of owners that may be created on a single day. A create is rejected once this
102	     * many owners already carry the current day as their {@code registrationDate}.
103	     */
104	    private static final int DAILY_OWNER_LIMIT = 100;
105	
106	    private final ClinicService clinicService;
107	
108	    private final OwnerMapper ownerMapper;
109	
110	    private final PetMapper petMapper;
111	
112	    private final VisitMapper visitMapper;
113	
114	    public OwnerRestControllerV1(ClinicService clinicService,
115	                                 OwnerMapper ownerMapper,
116	                                 PetMapper petMapper,
117	                                 VisitMapper visitMapper) {
118	        this.clinicService = clinicService;
119	        this.ownerMapper = ownerMapper;
120	        this.petMapper = petMapper;
121	        this.visitMapper = visitMapper;
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
127	        Collection<Owner> owners;
128	        if (lastName != null) {
129	            owners = this.clinicService.findOwnerByLastName(lastName);
130	        } else {
131	            owners = this.clinicService.findAllOwners();
132	        }
133	        if (owners.isEmpty()) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
142	        Owner owner = this.clinicService.findOwnerById(ownerId);
143	        if (owner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
152	        validateRequiredFields(ownerFieldsDto);
153	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
154	        HttpHeaders headers = new HttpHeaders();
155	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
156	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
157	        rejectFutureRegistrationDate(owner.getRegistrationDate());
158	        LocalDate effectiveDate = owner.getRegistrationDate() == null
159	            ? LocalDate.now()
160	            : owner.getRegistrationDate();
161	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
162	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
163	        rejectWhenCityAtCapacity(owner.getCity());
164	        applyHousehold(owner);
165	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
166	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
167	        rejectDuplicateIdentity(owner);
168	        owner.setCustomerCode(customerCode(owner));
169	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
170	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
171	        this.clinicService.saveOwner(owner);
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
174	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
175	            ownerDto.getMembershipLevel());
176	        headers.setLocation(UriComponentsBuilder.newInstance()
177	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
178	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    /**
182	     * Builds the owner's customer code, formatted {@code <REGION>-<HASH8>} where REGION is the region
183	     * code derived from the owner's postcode (falling back to the city-to-region table, then
184	     * {@code UNKNOWN}) and HASH8 is the first 8 upper-cased hex characters of the SHA-256 of the
185	     * owner's normalized telephone concatenated with its last name (e.g. {@code NSW-1A2B3C4D}). The
186	     * code is a pure function of the owner's region and identity, carrying no sequence number.
187	     *
188	     * @param owner the owner being created, with its normalized telephone already applied
189	     * @return the assigned customer code
190	     */
191	    private String customerCode(Owner owner) {
192	        return regionCode(owner) + "-" + identityHash8(owner.getTelephone(), owner.getLastName());
193	    }
194	
195	    /**
196	     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
197	     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
198	     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
199	     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
200	     * postcode nor the city identifies a region.
201	     *
202	     * @param owner the owner being created
203	     * @return the derived region code, never {@code null}
204	     */
205	    private String regionCode(Owner owner) {
206	        String fromPostcode = regionFromPostcode(owner.getPostcode());
207	        if (fromPostcode != null) {
208	            return fromPostcode;
209	        }
210	        String fromCity = region(owner.getCity());
211	        return fromCity == null ? "UNKNOWN" : fromCity;
212	    }
213	
214	    /**
215	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
216	     * postcode is absent, not 4 digits, or in no known range.
217	     *
218	     * @param postcode the owner's postcode, may be {@code null}
219	     * @return the region code, or {@code null} when no known range contains the postcode
220	     */
221	    private String regionFromPostcode(String postcode) {
222	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
223	            return null;
224	        }
225	        int value = Integer.parseInt(postcode);
226	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
227	            int[] range = entry.getValue();
228	            if (value >= range[0] && value <= range[1]) {
229	                return entry.getKey();
230	            }
231	        }
232	        return null;
233	    }
234	
235	    /**
236	     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
237	     * characters of the SHA-256 of the owner's normalized telephone concatenated with its last name.
238	     *
239	     * @param telephone the owner's normalized (E.164) telephone
240	     * @param lastName  the owner's last name
241	     * @return the 8-character upper-cased hex hash
242	     */
243	    private String identityHash8(String telephone, String lastName) {
244	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
245	        try {
246	            byte[] digest = MessageDigest.getInstance("SHA-256")
247	                .digest(input.getBytes(StandardCharsets.UTF_8));
248	            StringBuilder hex = new StringBuilder(digest.length * 2);
249	            for (byte b : digest) {
250	                hex.append(String.format("%02x", b));
251	            }
252	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
253	        } catch (NoSuchAlgorithmException ex) {
254	            throw new IllegalStateException("SHA-256 not available", ex);
255	        }
256	    }
257	
258	    /**
259	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
260	     * last two digits of the registrationDate year, zero-padded (e.g. {@code NSW-1A2B3C4D-M26}).
261	     *
262	     * @param customerCode     the owner's assigned customer code
263	     * @param registrationDate the owner's registration date
264	     * @return the assigned membership number
265	     */
266	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
267	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
268	    }
269	
270	    /**
271	     * Counts the existing owners that already share the given firstName and lastName, compared
272	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
273	     * the owners that pre-existed this create.
274	     *
275	     * @param firstName the new owner's first name
276	     * @param lastName  the new owner's last name
277	     * @return the number of existing namesakes
278	     */
279	    private int countNamesakes(String firstName, String lastName) {
280	        return (int) this.clinicService.findAllOwners().stream()
281	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
282	                && equalsIgnoreCase(existing.getLastName(), lastName))
283	            .count();
284	    }
285	
286	    /**
287	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
288	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
289	     * customer-code sequence is derived.
290	     *
291	     * @param city the new owner's city
292	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
293	     */
294	    private void rejectWhenCityAtCapacity(String city) {
295	        long count = this.clinicService.findAllOwners().stream()
296	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
297	            .count();
298	        if (count >= CITY_CAPACITY) {
299	            throw new CityAtCapacityException(city);
300	        }
301	    }
302	
303	    /**
304	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
305	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
306	     * business-day registration date, so the limit is enforced per business day and weekend
307	     * requests count against the Monday they roll forward to.
308	     *
309	     * @param registrationDate the owner's adjusted (business-day) registration date
310	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
311	     *                                  registration date
312	     */
313	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
314	        long count = this.clinicService.findAllOwners().stream()
315	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
316	            .count();
317	        if (count >= DAILY_OWNER_LIMIT) {
318	            throw new DailyOwnerLimitException(registrationDate);
319	        }
320	    }
321	
322	    /**
323	     * Rejects creating an owner whose supplied {@code registrationDate} lies in the future, i.e. is
324	     * later than the current server date. A {@code null} registration date is accepted (it defaults
325	     * to the server date) and today or any past date is allowed; only a future value is rejected.
326	     *
327	     * @param registrationDate the registration date supplied on the request, may be {@code null}
328	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
329	     */
330	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
331	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
332	            throw new FutureRegistrationDateException(registrationDate);
333	        }
334	    }
335	
336	    /**
337	     * Rolls a registration date forward onto a business day: when it falls on a Saturday or Sunday
338	     * it advances to the following Monday, otherwise it is returned unchanged. Applied to the
339	     * effective registration date (whether supplied in the request or defaulted to the server date)
340	     * so a weekend value never persists as an owner's {@code registrationDate}.
341	     *
342	     * @param date the effective registration date
343	     * @return the same date when it is a weekday, otherwise the next Monday
344	     */
345	    private LocalDate toBusinessDay(LocalDate date) {
346	        return switch (date.getDayOfWeek()) {
347	            case SATURDAY -> date.plusDays(2);
348	            case SUNDAY -> date.plusDays(1);
349	            default -> date;
350	        };
351	    }
352	
353	    private boolean equalsIgnoreCase(String a, String b) {
354	        return a == null ? b == null : a.equalsIgnoreCase(b);
355	    }
356	
357	    /**
358	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
359	     * offending field so the client learns about all of them at once.
360	     *
361	     * @param ownerFieldsDto the submitted owner fields
362	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
363	     *                                     missing or blank
364	     */
365	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
366	        List<String> errors = new ArrayList<>();
367	        if (isBlank(ownerFieldsDto.getFirstName())) {
368	            errors.add("firstName");
369	        }
370	        if (isBlank(ownerFieldsDto.getLastName())) {
371	            errors.add("lastName");
372	        }
373	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
374	            errors.add("address");
375	        }
376	        if (isBlank(ownerFieldsDto.getCity())) {
377	            errors.add("city");
378	        }
379	        if (isBlank(ownerFieldsDto.getTelephone())) {
380	            errors.add("telephone");
381	        }
382	        if (!errors.isEmpty()) {
383	            throw new MissingOwnerFieldsException(errors);
384	        }
385	    }
386	
387	    private boolean isBlank(String value) {
388	        return value == null || value.isBlank();
389	    }
390	
391	    /**
392	     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
393	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
394	     */
395	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
396	        "NSW", new int[] {2000, 2099},
397	        "VIC", new int[] {3000, 3099},
398	        "QLD", new int[] {4000, 4099});
399	
400	    /**
401	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
402	     * is optional and accepted, keeping the create contract backward-compatible. When present the
403	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
404	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
405	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
406	     *
407	     * @param postcode the raw postcode value as submitted, may be {@code null}
408	     * @param city     the owner's city, used to resolve the region whose range applies
409	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
410	     *                                  the city's region
411	     */
412	    private void validatePostcode(String postcode, String city) {
413	        if (isBlank(postcode)) {
414	            return;
415	        }
416	        if (!postcode.matches("[0-9]{4}")) {
417	            throw new InvalidPostcodeException(postcode, city);
418	        }
419	        String region = region(city);
420	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
421	        if (range != null) {
422	            int value = Integer.parseInt(postcode);
423	            if (value < range[0] || value > range[1]) {
424	                throw new InvalidPostcodeException(postcode, city);
425	            }
426	        }
427	    }
428	
429	    /**
430	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
431	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
432	     *
433	     * @param city the owner's city
434	     * @return the region code, or {@code null} when the city has no known region
435	     */
436	    private String region(String city) {
437	        if (city == null) {
438	            return null;
439	        }
440	        return switch (city) {
441	            case "Sydney" -> "NSW";
442	            case "Melbourne" -> "VIC";
443	            case "Brisbane" -> "QLD";
444	            default -> null;
445	        };
446	    }
447	
448	    /**
449	     * The number of national (subscriber) digits an E.164 number must carry for a given country
450	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
451	     * national digits and the North American Numbering Plan ('+1') requires 10.
452	     */
453	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
454	        Map.of("61", 9, "1", 10);
455	
456	    /**
457	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
458	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
459	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
460	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
461	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
462	     *
463	     * @param telephone the raw telephone value as submitted
464	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
465	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
466	     *                                   national-number length is wrong for its country code
467	     */
468	    private String normalizeTelephone(String telephone) {
469	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
470	        String nationalSignificantNumber;
471	        if (cleaned.startsWith("+")) {
472	            nationalSignificantNumber = cleaned.substring(1);
473	        } else {
474	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
475	            nationalSignificantNumber = "61" + national;
476	        }
477	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
478	            throw new InvalidTelephoneException(telephone);
479	        }
480	        validateNationalNumberLength(nationalSignificantNumber, telephone);
481	        return "+" + nationalSignificantNumber;
482	    }
483	
484	    /**
485	     * Validates the national-number length of an E.164 number against its country calling code. The
486	     * significant number is a country code immediately followed by the national digits; for each
487	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
488	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
489	     * left unchecked.
490	     *
491	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
492	     * @param rejectedValue             the raw telephone value, reported on rejection
493	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
494	     */
495	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
496	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
497	            String countryCode = rule.getKey();
498	            if (nationalSignificantNumber.startsWith(countryCode)) {
499	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
500	                if (nationalDigits != rule.getValue()) {
501	                    throw new InvalidTelephoneException(rejectedValue);
502	                }
503	                return;
504	            }
505	        }
506	    }
507	
508	    /**
509	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
510	     * value is treated as absent and returns {@code null}); when present the value must be a
511	     * syntactically valid address, and is stored and returned lower-cased.
512	     *
513	     * @param email the raw email value as submitted, may be {@code null}
514	     * @return the lower-cased email, or {@code null} when none was supplied
515	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
516	     */
517	    private String normalizeEmail(String email) {
518	        if (email == null || email.isBlank()) {
519	            return null;
520	        }
521	        String normalized = email.trim().toLowerCase();
522	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
523	            throw new InvalidEmailException(email);
524	        }
525	        return normalized;
526	    }
527	
528	    /**
529	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
530	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
531	     * key is the normalized telephone, email and householdId joined together, this one check
532	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
533	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
534	     * with different telephones have different keys and are both allowed.
535	     *
536	     * @param owner the owner being created, with its normalized telephone, email and householdId
537	     *              already applied
538	     * @throws DuplicateIdentityException if another owner already has the same identityKey
539	     */
540	    private void rejectDuplicateIdentity(Owner owner) {
541	        String identityKey = identityKey(owner);
542	        boolean inUse = this.clinicService.findAllOwners().stream()
543	            .map(this::identityKey)
544	            .anyMatch(identityKey::equals);
545	        if (inUse) {
546	            throw new DuplicateIdentityException(identityKey);
547	        }
548	    }
549	
550	    /**
551	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
552	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
553	     * duplicate decision is made by comparing whole identityKeys.
554	     *
555	     * @param owner the owner whose identityKey to derive
556	     * @return the derived identityKey
557	     */
558	    private String identityKey(Owner owner) {
559	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
560	        String email = owner.getEmail() == null ? "" : owner.getEmail();
561	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
562	        return telephone + "|" + email + "|" + householdId;
563	    }
564	
565	    /**
566	     * Applies the household rule to an owner being created. An owner belongs to the same household
567	     * as an existing owner when their lastName and address both match (compared case-insensitively
568	     * with runs of whitespace collapsed to a single space).
569	     *
570	     * <p>When no such existing owner exists there is nothing to do. Otherwise the new owner and
571	     * every existing owner in the household are assigned the same stable
572	     * {@link #householdId(String, String) householdId}. The household itself is no longer a
573	     * rejection: duplicate detection is now decided solely by the whole {@code identityKey}, of
574	     * which the householdId is one segment, so two members of the same household with different
575	     * telephones have different keys and are both allowed.
576	     *
577	     * @param owner the owner being created
578	     */
579	    private void applyHousehold(Owner owner) {
580	        String lastNameKey = toHouseholdKey(owner.getLastName());
581	        String addressKey = toHouseholdKey(owner.getAddress());
582	        List<Owner> household = this.clinicService.findAllOwners().stream()
583	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
584	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
585	            .toList();
586	        if (household.isEmpty()) {
587	            return;
588	        }
589	        String householdId = householdId(lastNameKey, addressKey);
590	        owner.setHouseholdId(householdId);
591	        for (Owner existing : household) {
592	            if (!householdId.equals(existing.getHouseholdId())) {
593	                existing.setHouseholdId(householdId);
594	                this.clinicService.saveOwner(existing);
595	            }
596	        }
597	    }
598	
599	    /**
600	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
601	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
602	     * lastName and address keys. Being a pure function of the household, every owner in it derives
603	     * the same value regardless of creation order.
604	     *
605	     * @param lastNameKey the normalized household lastName key
606	     * @param addressKey  the normalized household address key
607	     * @return the household identifier
608	     */
609	    private String householdId(String lastNameKey, String addressKey) {
610	        try {
611	            byte[] digest = MessageDigest.getInstance("SHA-256")
612	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
613	            StringBuilder hex = new StringBuilder(digest.length * 2);
614	            for (byte b : digest) {
615	                hex.append(String.format("%02x", b));
616	            }
617	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
618	        } catch (NoSuchAlgorithmException ex) {
619	            throw new IllegalStateException("SHA-256 not available", ex);
620	        }
621	    }
622	
623	    /**
624	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
625	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
626	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
627	     * string.
628	     */
629	    private String toHouseholdKey(String value) {
630	        if (value == null) {
631	            return "";
632	        }
633	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
634	    }
635	
636	    /**
637	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
638	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
639	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
640	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
641	     * value, or one that is blank once trimmed, normalizes to an empty string.
642	     *
643	     * @param address the raw address value as submitted, may be {@code null}
644	     * @return the normalized address, or an empty string when none was supplied
645	     */
646	    private String normalizeAddress(String address) {
647	        if (address == null) {
648	            return "";
649	        }
650	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
651	        if (collapsed.isEmpty()) {
652	            return "";
653	        }
654	        String[] tokens = collapsed.split(" ");
655	        StringBuilder normalized = new StringBuilder(collapsed.length());
656	        for (int i = 0; i < tokens.length; i++) {
657	            if (i > 0) {
658	                normalized.append(' ');
659	            }
660	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
661	        }
662	        return normalized.toString();
663	    }
664	
665	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
666	    @Override
667	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
668	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
669	        if (currentOwner == null) {
670	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
671	        }
672	        currentOwner.setAddress(ownerFieldsDto.getAddress());
673	        currentOwner.setCity(ownerFieldsDto.getCity());
674	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
675	        currentOwner.setLastName(ownerFieldsDto.getLastName());
676	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
677	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
678	        this.clinicService.saveOwner(currentOwner);
679	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
680	    }
681	
682	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
683	    @Transactional
684	    @Override
685	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
686	        Owner owner = this.clinicService.findOwnerById(ownerId);
687	        if (owner == null) {
688	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
689	        }
690	        this.clinicService.deleteOwner(owner);
691	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
692	    }
693	
694	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
695	    @Override
696	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
697	        Owner owner = this.clinicService.findOwnerById(ownerId);
698	        if (owner == null) {
699	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
700	        }
701	        HttpHeaders headers = new HttpHeaders();
702	        Pet pet = petMapper.toPet(petFieldsDto);
703	        owner.setId(ownerId);
704	        pet.setOwner(owner);
705	        pet.getType().setName(null);
706	        this.clinicService.savePet(pet);
707	        PetDto petDto = petMapper.toPetDto(pet);
708	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
709	            .buildAndExpand(pet.getId()).toUri());
710	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
711	    }
712	
713	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
714	    @Override
715	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
716	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
717	        if (currentOwner != null) {
718	            Pet currentPet = this.clinicService.findPetById(petId);
719	            if (currentPet != null) {
720	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
721	                currentPet.setName(petFieldsDto.getName());
722	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
723	                this.clinicService.savePet(currentPet);
724	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
725	            }
726	        }
727	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
728	    }
729	
730	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
731	    @Override
732	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
733	        HttpHeaders headers = new HttpHeaders();
734	        Visit visit = visitMapper.toVisit(visitFieldsDto);
735	        Pet pet = new Pet();
736	        pet.setId(petId);
737	        visit.setPet(pet);
738	        this.clinicService.saveVisit(visit);
739	        VisitDto visitDto = visitMapper.toVisitDto(visit);
740	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
741	            .buildAndExpand(visit.getId()).toUri());
742	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
743	    }
744	
745	
746	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
747	    @Override
748	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
749	        Owner owner = this.clinicService.findOwnerById(ownerId);
750	        if (owner != null) {
751	            Pet pet = owner.getPet(petId);
752	            if (pet != null) {
753	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
754	            }
755	        }
756	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
757	    }
758	}
